import pandas as pd, numpy as np, re
lab=pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)
cols=[c for c in lab.columns if c!='patient_id']
missing={'','nan','NaN','None','NULL','null','NA','N/A'}
keep=re.compile(r'[^0-9eE+\-\.,]')

def parse(v):
    if v is None or (isinstance(v,float) and np.isnan(v)):
        return np.nan
    s=str(v).strip()
    if s in missing or s.lower()=='nan':
        return np.nan
    s=keep.sub('', s)
    if ',' in s and '.' in s:
        s=s.replace(',','')
    elif ',' in s:
        s=s.replace(',','.')
    try:
        return float(s)
    except:
        return np.nan

parsed=lab.copy()
for c in cols:
    parsed[c]=lab[c].map(parse)

# drop missing rows
mask=parsed[cols].notna().all(axis=1)
parsed=parsed[mask]
print('rows after complete-case drop', len(parsed))

def stats(c):
    x=parsed[c].to_numpy()
    return dict(min=np.nanmin(x), p1=np.nanpercentile(x,1), p50=np.nanpercentile(x,50), p99=np.nanpercentile(x,99), max=np.nanmax(x))

suspects=['Serum_Creatinine','BUN','Magnesium','Serum_Calcium','Phosphorus','Hemoglobin','Hematocrit','Albumin_Serum','Total_Protein','Total_Bilirubin','Direct_Bilirubin','Total_Cholesterol','Triglycerides','Troponin_I','Troponin_T','pCO2_Arterial','pO2_Arterial','Lactate','Vitamin_D_25OH','HbA1c','CRP','Urine_Protein','Urine_Albumin','Urine_Creatinine']
for c in suspects:
    st=stats(c)
    print(f"{c:30s} min {st['min']:.4g} p1 {st['p1']:.4g} p50 {st['p50']:.4g} p99 {st['p99']:.4g} max {st['max']:.4g}")
PY"}

